class ProductionLearningKeyTest {

	private static final LogicalLearningKey LOGICAL = LogicalLearningKey.of("difference", "expr-a", "children-a",
			"predicates-a", "v0,v1", "none", "bag|duplicate-sensitive|minus-compatible-domain", "default");
	private static final LearningApplicability APPLICABILITY = new LearningApplicability(11L, 0L,
			"unconditional", 19L, 23L, 1L);
	private static final PhysicalResidualKey STREAMING = PhysicalResidualKey.of("streaming", "direct", "spoc",
			"dependent-reopen", "none", "none", "none", "layout-a");
	private static final PhysicalResidualKey MATERIALIZED = PhysicalResidualKey.of("materialized", "hash", "none",
			"single-open", "materialized", "medium", "unconditional", "layout-a");

	@Test
	void logicalCardinalityIsSymmetricAcrossPhysicalAlternatives() {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observeLogical(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d, 400.0d, 1L);

		double streamingRows = rawLogicalEstimate(model, LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS,
				100.0d).correctedValue();
		double materializedRows = rawLogicalEstimate(model, LOGICAL, APPLICABILITY,
				FrontierCostDimension.OUTPUT_ROWS,
				100.0d).correctedValue();

		assertEquals(streamingRows, materializedRows, 0.0d,
				"Every implementation of one memo expression starts from identical logical truth");
	}

	@Test
	void physicalResidualDoesNotLeakToSiblingAlgorithm() {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observePhysical(LOGICAL, STREAMING, APPLICABILITY, FrontierCostDimension.EXHAUSTION_WORK,
				10.0d, 1_000.0d, 1L);

		assertTrue(rawPhysicalEstimate(model, LOGICAL, STREAMING, APPLICABILITY,
				FrontierCostDimension.EXHAUSTION_WORK, 10.0d).correctedValue() > 10.0d);
		assertNull(rawPhysicalEstimate(model, LOGICAL, MATERIALIZED, APPLICABILITY,
				FrontierCostDimension.EXHAUSTION_WORK, 10.0d),
				"An unexecuted algorithm must not inherit another algorithm's work residual");
	}

	@Test
	void exactExpressionAndApplicabilityMayShareAcrossQueries() {
		LogicalLearningKey q9 = LogicalLearningKey.parse(LOGICAL.externalForm());
		LogicalLearningKey q10 = LogicalLearningKey.of("DIFFERENCE", "expr-a", "children-a", "predicates-a",
				"v0,v1", "none", "bag|duplicate-sensitive|minus-compatible-domain", "default");

		assertEquals(q9, q10, "Query-local spelling must not change an alpha-normalized canonical key");
		assertEquals(APPLICABILITY, LearningApplicability.parse(APPLICABILITY.externalForm()));
	}

	@Test
	void differingApplicabilityNeverSharesLogicalPosterior() {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observeLogical(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d, 400.0d, 1L);
		LearningApplicability correlated = new LearningApplicability(11L, 29L, "correlated:7", 19L, 23L, 1L);

		assertNull(model.logicalEstimate(LOGICAL, correlated, FrontierCostDimension.OUTPUT_ROWS, 100.0d));
	}

	@Test
	void savedRawPredictionPreventsDoubleCorrection() {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observeLogical(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d, 400.0d, 1L);

		double first = rawLogicalEstimate(model, LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d)
				.correctedValue();
		double second = rawLogicalEstimate(model, LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d)
				.correctedValue();

		assertEquals(first, second, 0.0d, "Planning reads a posterior against the saved raw estimate exactly once");
	}

	@Test
	void logicalCardinalityTruthDoesNotScaleWithAChangedRawEstimate() {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observeLogical(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d, 400.0d, 1L);

		double firstRawEstimate = rawLogicalEstimate(model,
				LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d)
						.correctedValue();
		double changedRawEstimate = rawLogicalEstimate(model,
				LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 200.0d)
						.correctedValue();

		assertEquals(firstRawEstimate, changedRawEstimate, 0.0d,
				"A logical posterior represents expression cardinality, not a residual that compounds with child learning");
	}

	@Test
	void logicalCardinalityUsesCommensurateInvocationSumsWithoutBecomingTheirTotal() {
		FrontierLearningModel model = new FrontierLearningModel();
		FrontierLearningModel canonicalObservation = new FrontierLearningModel();
		canonicalObservation.observeLogical(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS,
				49_800.0d, 49_800.0d, 1L);
		FrontierLearningModel.ResolvedCells cells = model.resolve(
				LOGICAL, STREAMING, APPLICABILITY, true, false);
		RuntimeFeedbackContract contract = contract(STREAMING, 49_800.0d);
		RuntimeFeedbackAccumulator target = target(model, cells, contract);

		for (int open = 0; open < 2; open++) {
			target.open();
			target.close(49_800L, 49_800.0d, 49_800L, 0L, 0L, 0L, 0L, 0L, 0L, 0L,
					EvaluationStatistics.TerminationClassification.EXHAUSTED);
		}
		target.publish(true);

		assertEquals(99_600.0d, target.rawPredictedRowsSum(), 0.0d);
		assertEquals(99_600.0d, target.actualRowsSum(), 0.0d);
		assertEquals(rawLogicalEstimate(canonicalObservation,
				LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 49_800.0d)
						.correctedValue(),
				rawLogicalEstimate(model,
						LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 49_800.0d)
								.correctedValue(),
				0.0d,
				"The summed execution observation calibrates the saved raw cardinality; it is not itself one-open truth");
	}

	@Test
	void varyingOpenPredictionsCalibrateTheSavedRawCardinalityFromExactSums() {
		FrontierLearningModel model = new FrontierLearningModel();
		FrontierLearningModel canonicalObservation = new FrontierLearningModel();
		canonicalObservation.observeLogical(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS,
				100.0d, 200.0d, 1L);
		FrontierLearningModel.ResolvedCells cells = model.resolve(
				LOGICAL, STREAMING, APPLICABILITY, true, false);
		RuntimeFeedbackContract contract = contract(STREAMING, 100.0d);
		RuntimeFeedbackAccumulator target = target(model, cells, contract);
		double[] predictedRows = { 1.0d, 10.0d, 100.0d };
		long[] actualRows = { 2L, 20L, 200L };

		for (int open = 0; open < predictedRows.length; open++) {
			RuntimeFeedbackContract.PredictionVector prediction = prediction(predictedRows[open]);
			target.open(prediction, prediction);
			target.close(actualRows[open], actualRows[open], actualRows[open], 0L, 0L, 0L, 0L, 0L, 0L, 0L,
					EvaluationStatistics.TerminationClassification.EXHAUSTED);
		}
		target.publish(true);

		assertEquals(111.0d, target.rawPredictedRowsSum(), 0.0d);
		assertEquals(222.0d, target.actualRowsSum(), 0.0d);
		assertEquals(rawLogicalEstimate(canonicalObservation,
				LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d)
						.correctedValue(),
				rawLogicalEstimate(model,
						LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d)
								.correctedValue(),
				0.0d,
				"The aggregate ratio must use the explicit open-time prediction vector, not an opens divisor");
	}

	@Test
	void typedLogicalAndPhysicalStoresRoundTripIndependently() throws Exception {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observeLogical(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d, 400.0d, 1L);
		model.observePhysical(LOGICAL, STREAMING, APPLICABILITY, FrontierCostDimension.FIRST_MATCH_WORK,
				2.0d, 20.0d, 2L);
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (DataOutputStream out = new DataOutputStream(bytes)) {
			model.writeTo(out);
		}

		FrontierLearningModel restored;
		try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			restored = FrontierLearningModel.readFrom(in);
		}

		assertTrue(rawLogicalEstimate(restored, LOGICAL, APPLICABILITY,
				FrontierCostDimension.OUTPUT_ROWS, 100.0d)
						.correctedValue() > 100.0d);
		assertTrue(rawPhysicalEstimate(restored, LOGICAL, STREAMING, APPLICABILITY,
				FrontierCostDimension.FIRST_MATCH_WORK, 2.0d).correctedValue() > 2.0d);
		assertNull(rawPhysicalEstimate(restored, LOGICAL, MATERIALIZED, APPLICABILITY,
				FrontierCostDimension.FIRST_MATCH_WORK, 2.0d));
	}

	@Test
	void keyVersionsRejectAmbiguousLegacyForms() {
		assertNull(LogicalLearningKey.parse("flk1|legacy"));
		assertNull(PhysicalResidualKey.parse("flk1|legacy"));
		assertNull(LearningApplicability.parse("flk1|legacy"));
		assertNotEquals(LOGICAL.digest(), STREAMING.digest());
	}

	@Test
	void physicalAccessKernelIgnoresLearnedEstimateProvenance() {
		PackedCostEstimate raw = accessEstimate("lmdb-frontier", 2, 0, 1);
		PackedCostEstimate learned = accessEstimate("lmdb-frontier+leo", 2, 0, 1);
		PackedCostEstimate differentLookup = accessEstimate("lmdb-frontier+leo", 3, 0, 2);

		assertEquals(LmdbFrontierPackedCostSession.learningAccessKernel(raw),
				LmdbFrontierPackedCostSession.learningAccessKernel(learned),
				"Applying feedback must not rename the physical access implementation");
		assertNotEquals(LmdbFrontierPackedCostSession.learningAccessKernel(raw),
				LmdbFrontierPackedCostSession.learningAccessKernel(differentLookup),
				"Different lookup shapes remain isolated physical kernels");
	}

	@Test
	void preboundAlternativesShareLogicalCellAndIsolatePhysicalCells() {
		FrontierLearningModel model = new FrontierLearningModel();
		FrontierLearningModel.ResolvedCells streaming = model.resolve(
				LOGICAL, STREAMING, APPLICABILITY, true, true);
		FrontierLearningModel.ResolvedCells materialized = model.resolve(
				LOGICAL, MATERIALIZED, APPLICABILITY, true, true);

		assertTrue(streaming.sharesLogicalCell(materialized));
		assertFalse(streaming.sharesPhysicalCell(materialized));

		RuntimeFeedbackContract streamingContract = contract(STREAMING);
		RuntimeFeedbackAccumulator target = target(model, streaming, streamingContract);
		target.open();
		target.close(400L, 1_000.0d, 1_000L, 10L, 0L, 0L, 0L, 0L, 0L, 0L,
				EvaluationStatistics.TerminationClassification.EXHAUSTED);
		target.recordActualPhysicalImplementation(streamingContract.physicalImplementationId());
		target.publish(true);
		model.release(materialized);

		assertTrue(rawLogicalEstimate(model, LOGICAL, APPLICABILITY,
				FrontierCostDimension.OUTPUT_ROWS, 100.0d)
						.correctedValue() > 100.0d);
		assertTrue(rawPhysicalEstimate(model, LOGICAL, STREAMING, APPLICABILITY,
				FrontierCostDimension.SOURCE_ROWS_SCANNED, 100.0d).correctedValue() > 100.0d);
		assertNull(rawPhysicalEstimate(model, LOGICAL, MATERIALIZED, APPLICABILITY,
				FrontierCostDimension.SOURCE_ROWS_SCANNED, 100.0d));
	}

	@Test
	void activeCellsPreventCapacityEvictionUntilLeaseRelease() {
		FrontierLearningModel model = new FrontierLearningModel(1);
		FrontierLearningModel.ResolvedCells active = model.resolve(
				LOGICAL, STREAMING, APPLICABILITY, true, true);

		assertNull(model.resolve(LOGICAL, MATERIALIZED, APPLICABILITY, true, true),
				"Capacity made entirely of active cells must compile a no-op target");

		model.release(active);
		FrontierLearningModel.ResolvedCells admitted = model.resolve(
				LOGICAL, MATERIALIZED, APPLICABILITY, true, true);
		assertTrue(admitted != null);
		model.release(admitted);
	}

	@Test
	void generationChangeRejectsOutstandingPreboundObservation() {
		FrontierLearningModel model = new FrontierLearningModel();
		FrontierLearningModel.ResolvedCells cells = model.resolve(
				LOGICAL, STREAMING, APPLICABILITY, true, true);
		RuntimeFeedbackContract contract = contract(STREAMING);
		RuntimeFeedbackAccumulator target = new RuntimeFeedbackAccumulator(contract,
				new RuntimeFeedbackAccumulator.Destination() {
					@Override
					public void publish(InvocationAggregateView observation) {
						assertFalse(model.observeResolved(cells, contract, observation, 1L));
					}

					@Override
					public void release() {
						model.release(cells);
					}
				});
		target.open();
		target.close(400L, 1_000.0d, 1_000L, 10L, 0L, 0L, 0L, 0L, 0L, 0L,
				EvaluationStatistics.TerminationClassification.EXHAUSTED);

		model.clear();
		target.publish(true);

		assertNull(model.logicalEstimate(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d));
	}

	private static FrontierLearningModel.DimensionEstimate rawLogicalEstimate(FrontierLearningModel model,
			LogicalLearningKey logicalKey, LearningApplicability applicability, FrontierCostDimension dimension,
			double predicted) {
		return FrontierLearningModel.estimateLogical(model.logicalPosterior(logicalKey, applicability, dimension),
				dimension, predicted);
	}

	private static FrontierLearningModel.DimensionEstimate rawPhysicalEstimate(FrontierLearningModel model,
			LogicalLearningKey logicalKey, PhysicalResidualKey physicalKey, LearningApplicability applicability,
			FrontierCostDimension dimension, double predicted) {
		return FrontierLearningModel.estimate(
				model.physicalPosterior(logicalKey, physicalKey, applicability, dimension), predicted);
	}

	private static RuntimeFeedbackAccumulator target(FrontierLearningModel model,
			FrontierLearningModel.ResolvedCells cells, RuntimeFeedbackContract contract) {
		return new RuntimeFeedbackAccumulator(contract, new RuntimeFeedbackAccumulator.Destination() {
			@Override
			public void publish(InvocationAggregateView observation) {
				assertTrue(model.observeResolved(cells, contract, observation, 1L));
			}

			@Override
			public void release() {
				model.release(cells);
			}
		});
	}

	private static RuntimeFeedbackContract contract(PhysicalResidualKey physicalKey) {
		return contract(physicalKey, 100.0d);
	}

	private static RuntimeFeedbackContract contract(PhysicalResidualKey physicalKey, double predictedRows) {
		RuntimeFeedbackContract.PredictionVector prediction = prediction(predictedRows);
		return new RuntimeFeedbackContract(
				new LmdbRuntimeFeedbackDescriptor(null, null, LOGICAL, APPLICABILITY, physicalKey),
				prediction, prediction, 90.0d, 100.0d, 110.0d, Double.POSITIVE_INFINITY,
				RuntimeFeedbackContract.SemanticKind.ORDINARY, RuntimeFeedbackContract.Algorithm.SCAN,
				RuntimeFeedbackContract.Access.EXACT_LOOKUP, physicalKey.hashCode(), 19L, 23L, 1L,
				RuntimeFeedbackContract.ADMIT_LOGICAL | RuntimeFeedbackContract.ADMIT_PHYSICAL);
	}

	private static RuntimeFeedbackContract.PredictionVector prediction(double rows) {
		return new RuntimeFeedbackContract.PredictionVector(
				rows, rows, rows, rows, 10.0d, 1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
	}

	private static PackedCostEstimate accessEstimate(String estimateSource, int lookupMask, int missingMask,
			int prefixLength) {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setRows(10.0d, 20.0d);
		estimate.setAccess(lookupMask, missingMask, prefixLength, 10.0d, 1.0d, "posc", estimateSource,
				"prefixScan");
		estimate.putPlannedStringMetric("plannedPhysicalImplementation", "materialized-minus-compatibility");
		return estimate;
	}
}
